import numpy as np


def assign_nearest(points, centres):
    P = np.asarray(points, dtype=float)
    C = np.asarray(centres, dtype=float)
    d = ((P[:, None, :] - C[None, :, :]) ** 2).sum(axis=2)
    return len(C) - 1 - d[:, ::-1].argmin(axis=1)

import numpy as np


def assign_nearest(points, centres):
    P = np.asarray(points, dtype=float)
    C = np.asarray(centres, dtype=float)
    d = np.abs(P[:, None, :] - C[None, :, :]).sum(axis=2)
    return d.argmin(axis=1)

